import{_ as d,C as l,o as s,c as i,a2 as n,b as e,w as a,a as o,E,a3 as A}from"./chunks/framework.BC3NdntU.js";const B=JSON.parse('{"title":"4.4 HTTPS 与 TLS","description":"","frontmatter":{},"headers":[],"relativePath":"卷四-网络与通信/4.4-HTTPS与TLS.md","filePath":"卷四-网络与通信/4.4-HTTPS与TLS.md","lastUpdated":1788776592000}'),p={name:"卷四-网络与通信/4.4-HTTPS与TLS.md"};function T(h,t,u,g,c,C){const r=l("Mermaid");return s(),i("div",null,[t[2]||(t[2]=n('<h1 id="_4-4-https-与-tls" tabindex="-1">4.4 HTTPS 与 TLS <a class="header-anchor" href="#_4-4-https-与-tls" aria-label="Permalink to &quot;4.4 HTTPS 与 TLS&quot;">​</a></h1><blockquote><p>卷:卷四 · 网络与通信 难度:⭐⭐⭐ 专家 | 阅读时间:25min | 状态:进行中</p></blockquote><hr><h2 id="引言-http-为什么不安全-https-加了三把锁" tabindex="-1">引言:HTTP 为什么不安全,HTTPS 加了三把锁 <a class="header-anchor" href="#引言-http-为什么不安全-https-加了三把锁" aria-label="Permalink to &quot;引言:HTTP 为什么不安全,HTTPS 加了三把锁&quot;">​</a></h2><p>HTTP 明文传输,有三大风险:<strong>窃听、篡改、冒充</strong>。HTTPS = HTTP + TLS,用「加密」防窃听、「完整性校验」防篡改、「证书」防冒充。理解它,面试&quot;HTTPS 原理&quot;才不是背书。</p><hr><h2 id="一、http-的三大风险-→-https-的三种对策" tabindex="-1">一、HTTP 的三大风险 → HTTPS 的三种对策 <a class="header-anchor" href="#一、http-的三大风险-→-https-的三种对策" aria-label="Permalink to &quot;一、HTTP 的三大风险 → HTTPS 的三种对策&quot;">​</a></h2><table tabindex="0"><thead><tr><th>风险</th><th>含义</th><th>HTTPS 对策</th></tr></thead><tbody><tr><td>窃听</td><td>明文可被抓包看光</td><td><strong>对称加密</strong>(数据加密)</td></tr><tr><td>篡改</td><td>中间人可改内容</td><td><strong>完整性校验</strong>(MAC/摘要)</td></tr><tr><td>冒充</td><td>无法确认对方身份</td><td><strong>证书 + 非对称加密</strong>(验身份)</td></tr></tbody></table><hr><h2 id="二、两种加密-对称-vs-非对称" tabindex="-1">二、两种加密:对称 vs 非对称 <a class="header-anchor" href="#二、两种加密-对称-vs-非对称" aria-label="Permalink to &quot;二、两种加密:对称 vs 非对称&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>对称加密</th><th>非对称加密</th></tr></thead><tbody><tr><td>密钥</td><td>一把,加解密同钥</td><td>一对公钥/私钥</td></tr><tr><td>速度</td><td><strong>快</strong></td><td><strong>慢</strong>(大数运算)</td></tr><tr><td>用法</td><td>加密数据本体</td><td>交换密钥、验签名</td></tr><tr><td>代表</td><td>AES、ChaCha20</td><td>RSA、ECDHE</td></tr></tbody></table><p><strong>核心思路:混合加密</strong></p><blockquote><p>非对称加密<strong>慢</strong>,不适合加密大量数据;对称加密<strong>快</strong>,但密钥怎么安全交给对方?答案:<strong>用非对称加密交换&quot;对称密钥&quot;,之后用对称加密传数据。</strong></p></blockquote>',13)),(s(),e(A,null,{default:a(()=>[E(r,{id:"mermaid-142",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20C%20as%20%E5%AE%A2%E6%88%B7%E7%AB%AF%0A%20%20%20%20participant%20S%20as%20%E6%9C%8D%E5%8A%A1%E5%99%A8%0A%20%20%20%20Note%20over%20C%2CS%3A%201.%20%E7%94%A8%E9%9D%9E%E5%AF%B9%E7%A7%B0%E5%8A%A0%E5%AF%86%E5%8D%8F%E5%95%86%E5%87%BA%E4%B8%80%E6%8A%8A%E3%80%8C%E5%AF%B9%E7%A7%B0%E5%AF%86%E9%92%A5%E3%80%8D%0A%20%20%20%20C-%3E%3ES%3A%20%E7%94%A8%E6%9C%8D%E5%8A%A1%E5%99%A8%E5%85%AC%E9%92%A5%E5%8A%A0%E5%AF%86%E7%9A%84%E6%8F%A1%E6%89%8B%E4%BF%A1%E6%81%AF%0A%20%20%20%20S--%3E%3EC%3A%20%E5%8D%8F%E5%95%86%E5%87%BA%E4%BC%9A%E8%AF%9D%E5%AF%86%E9%92%A5%0A%20%20%20%20Note%20over%20C%2CS%3A%202.%20%E4%B9%8B%E5%90%8E%E5%85%A8%E7%A8%8B%E7%94%A8%E3%80%8C%E5%AF%B9%E7%A7%B0%E5%AF%86%E9%92%A5%E3%80%8D%E5%8A%A0%E5%AF%86%E6%95%B0%E6%8D%AE%0A%20%20%20%20C-%3E%3ES%3A%20%E5%AF%B9%E7%A7%B0%E5%8A%A0%E5%AF%86(%E5%BF%AB)%E7%9A%84%E5%BA%94%E7%94%A8%E6%95%B0%E6%8D%AE%0A%20%20%20%20S--%3E%3EC%3A%20%E5%AF%B9%E7%A7%B0%E5%8A%A0%E5%AF%86(%E5%BF%AB)%E7%9A%84%E5%BA%94%E7%94%A8%E6%95%B0%E6%8D%AE%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[o(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=n('<hr><h2 id="三、证书与-ca-解决-公钥是谁的" tabindex="-1">三、证书与 CA:解决&quot;公钥是谁的&quot; <a class="header-anchor" href="#三、证书与-ca-解决-公钥是谁的" aria-label="Permalink to &quot;三、证书与 CA:解决&quot;公钥是谁的&quot;&quot;">​</a></h2><p>拿到公钥后,怎么确定它真的是目标服务器的、而非中间人伪造的?</p><ul><li><strong>证书</strong>:包含&quot;域名 + 该域名的公钥 + 签发者签名&quot;</li><li><strong>CA(Certificate Authority)</strong>:受信任的第三方,用它的私钥给证书签名</li><li>验证链:浏览器用<strong>内置的 CA 公钥</strong>验证书签名 → 确认&quot;这个公钥确实属于这个域名&quot;</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>证书链:服务器证书 → 中间 CA → 根 CA(浏览器内置信任)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><blockquote><p>篡改证书会被签名校验识破,冒充域名会拿不到对应域名的合法证书——这就是 HTTPS 防&quot;中间人&quot;的核心。</p></blockquote><hr><h2 id="四、tls-握手-简版" tabindex="-1">四、TLS 握手(简版) <a class="header-anchor" href="#四、tls-握手-简版" aria-label="Permalink to &quot;四、TLS 握手(简版)&quot;">​</a></h2>',8)),(s(),e(A,null,{default:a(()=>[E(r,{id:"mermaid-177",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20C%20as%20%E5%AE%A2%E6%88%B7%E7%AB%AF%0A%20%20%20%20participant%20S%20as%20%E6%9C%8D%E5%8A%A1%E5%99%A8%0A%20%20%20%20C-%3E%3ES%3A%20ClientHello(%E6%94%AF%E6%8C%81%E7%9A%84%20TLS%20%E7%89%88%E6%9C%AC%E3%80%81%E5%8A%A0%E5%AF%86%E5%A5%97%E4%BB%B6%E3%80%81%E9%9A%8F%E6%9C%BA%E6%95%B0)%0A%20%20%20%20S--%3E%3EC%3A%20ServerHello(%E9%80%89%E5%AE%9A%E5%A5%97%E4%BB%B6%E3%80%81%E9%9A%8F%E6%9C%BA%E6%95%B0)%2B%20%E8%AF%81%E4%B9%A6%0A%20%20%20%20Note%20over%20C%3A%20%E9%AA%8C%E8%AF%81%E4%B9%A6%20%E2%86%92%20%E7%94%9F%E6%88%90%E9%A2%84%E5%A4%87%E4%B8%BB%E5%AF%86%E9%92%A5%0A%20%20%20%20C-%3E%3ES%3A%20%E7%94%A8%E6%9C%8D%E5%8A%A1%E5%99%A8%E5%85%AC%E9%92%A5%E5%8A%A0%E5%AF%86%E7%9A%84%E5%AF%86%E9%92%A5%E4%BA%A4%E6%8D%A2%E5%8F%82%E6%95%B0%0A%20%20%20%20Note%20over%20C%2CS%3A%20%E5%8F%8C%E6%96%B9%E5%90%84%E8%87%AA%E7%AE%97%E5%87%BA%E3%80%8C%E4%BC%9A%E8%AF%9D%E5%AF%86%E9%92%A5%E3%80%8D%0A%20%20%20%20C-%3E%3ES%3A%20%E7%94%A8%E4%BC%9A%E8%AF%9D%E5%AF%86%E9%92%A5%E5%8A%A0%E5%AF%86%E7%9A%84%20Finished%0A%20%20%20%20S--%3E%3EC%3A%20Finished(%E6%8F%A1%E6%89%8B%E5%AE%8C%E6%88%90%2C%E8%BF%9B%E5%85%A5%E5%AF%B9%E7%A7%B0%E5%8A%A0%E5%AF%86%E9%80%9A%E4%BF%A1)%0A"})]),fallback:a(()=>[...t[1]||(t[1]=[o(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=n(`<blockquote><p>记忆要点:先<strong>验证书</strong>(防冒充)→ 再<strong>非对称交换密钥</strong>(防窃听密钥)→ 后<strong>对称加密通信</strong>(快)。</p></blockquote><hr><h2 id="五、http-1-1-→-2-→-3-演进一页" tabindex="-1">五、HTTP/1.1 → 2 → 3(演进一页) <a class="header-anchor" href="#五、http-1-1-→-2-→-3-演进一页" aria-label="Permalink to &quot;五、HTTP/1.1 → 2 → 3(演进一页)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>关键改进</th><th>痛点</th></tr></thead><tbody><tr><td>HTTP/1.1</td><td>持久连接(keep-alive)</td><td>队头阻塞、同一连接串行</td></tr><tr><td>HTTP/2</td><td><strong>多路复用</strong>(一连接多请求并发)、头部压缩(HPACK)、二进制分帧、服务器推送</td><td>底层仍 TCP,丢包仍队头阻塞</td></tr><tr><td>HTTP/3</td><td>基于 <strong>QUIC(UDP)</strong>、0-RTT 握手、彻底解决队头阻塞</td><td>新、UDP 相关中间设备适配</td></tr></tbody></table><blockquote><p>前端视角:HTTP/2 让&quot;合并文件/雪碧图&quot;这些老优化不再必要(多路复用本身就是并行);但要完整理解需到进阶场景。</p></blockquote><hr><h2 id="六、小结" tabindex="-1">六、小结 <a class="header-anchor" href="#六、小结" aria-label="Permalink to &quot;六、小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTPS = HTTP + TLS</span></span>
<span class="line"><span>三对策:对称加密(防窃听)+ 完整性校验(防篡改)+ 证书/CA(防冒充)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>混合加密:非对称(慢)换对称密钥 → 对称(快)传数据</span></span>
<span class="line"><span>证书链:服务器证书 → 中间CA → 根CA(浏览器信任)</span></span>
<span class="line"><span>演进:1.1(持久连接)→ 2(多路复用/头部压缩)→ 3(QUIC/UDP,根治队头阻塞)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><hr><h2 id="七、面试题" tabindex="-1">七、面试题 <a class="header-anchor" href="#七、面试题" aria-label="Permalink to &quot;七、面试题&quot;">​</a></h2><p><strong>Q1:为什么 HTTPS 用&quot;混合加密&quot;而不是纯非对称或纯对称?</strong></p><p>纯非对称<strong>太慢</strong>(大数运算,扛不住大流量);纯对称<strong>密钥分发不安全</strong>(明文发密钥等于没加密)。混合:非对称只用来<strong>安全交换</strong>对称密钥(少量数据、慢点没关系),之后大数据走对称加密(快),取两者之长。</p><p><strong>Q2:证书怎么防止被&quot;中间人&quot;伪造?</strong></p><p>①② 证书由受信任的 <strong>CA 签名</strong>;③ 伪造者即使自建证书,浏览器也会因<strong>根证书不信任</strong>而告警;④ 篡改证书内容会使<strong>签名校验不通过</strong>。所以中间人既拿不到真证书、也造不出能过签名的假证书。</p><p><strong>Q3:HTTP/2 的&quot;多路复用&quot;解决了什么问题?</strong></p><p>HTTP/1.1 同一连接上请求<strong>串行</strong>且有队头阻塞(前一个慢,后面全等)。HTTP/2 用<strong>二进制分帧</strong>,在同一条 TCP 连接上<strong>并发传输多个请求/响应流</strong>,消除队头阻塞、减少连接数、提升并发。(真正根治丢包级队头阻塞要等 HTTP/3 的 QUIC。)</p><hr><p>📎 参考:MDN《HTTPS》《TLS》、RFC 8446(TLS 1.3)、Google Developers《HTTP/3》</p>`,18))])}const S=d(p,[["render",T]]);export{B as __pageData,S as default};
